const body = $json.body ?? $json ?? {};
const claims = $json.jwtPayload ?? {};
const userId = claims.sub || body.user_id || '00000000-0000-4000-8000-000000000000';
const requestedCount = Math.min(90, Math.max(1, Number.parseInt(body.slide_count ?? '8', 10) || 8));
return [{
  json: {
    mode: body.mode === 'assistant' ? 'assistant' : 'generate',
    project_id: body.project_id || '00000000-0000-4000-8000-000000000000',
    session_id: body.session_id || '',
    user_id: userId,
    message: body.message || '',
    description: body.description || '',
    purpose: body.purpose || 'Sales',
    slide_count: requestedCount,
    style: body.style || 'modern',
    font_set: body.font_set || 'grotesk',
    palette: body.palette || 'clay',
    ratio: body.ratio || '16:9',
    slides: Array.isArray(body.slides) ? body.slides : [],
    selected_slide_id: body.selected_slide_id || null,
    messages: Array.isArray(body.messages) ? body.messages.slice(-30) : [],
    asset_context: body.asset_context || ''
  }
}];

