parameters.jsCode:
const source = $input.first().json;
const raw = source.output ?? source.text ?? source.response?.text ?? source;
let result = raw;
if (typeof raw === 'string') {
  try {
    result = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
  } catch {
    result = { reply: 'Here is your updated presentation.', slides: [] };
  }
}
if (result?.output) result = result.output;
if (!Array.isArray(result?.slides)) result.slides = [];
result.slides = result.slides.map((slide, index) => ({ ...slide, id: slide.id || ('slide-' + (index + 1)) }));
result.slideCount = result.slides.length || 8;
result.generated_at = new Date().toISOString();
const input = $('Verify User and Normalize').first().json;
const messages = [...input.messages];
const last = messages[messages.length - 1];
if (input.message && !(last?.role === 'user' && last?.text === input.message)) messages.push({ id: 'user-' + Date.now(), role: 'user', text: input.message });
messages.push({ id: 'assistant-' + Date.now(), role: 'assistant', text: result.reply || 'Presentation updated.' });
return [{ json: { ...result, actions: result, session_id: input.session_id, user_id: input.user_id, project_id: input.project_id, title: result.slides[0]?.title || 'Untitled presentation', messages, result } }];
